vfuncDefaults.GES.TimelineElement::get_layer_priority:
{
// The C answers the priority of the element itself for an empty
// slot (ges-timeline-element.c:2439-2440), which is the field the
// priority getter reads (:1444-1449): the element is in no layer, so
// its own priority is the only one it has.
return GesTimelineElementGetPriority(self);
}

vfuncDefaults.GstAudio.AudioBaseSink::payload:
{
// Payloading is what a sink does to data a device wants in another
// shape, and there is nothing below the override that wants one: the
// buffer is answered as it arrived, with the reference its caller takes
// over. That is what gst_audio_base_sink_render does for a NULL slot -
// it renders the buffer it already holds - and the gir says the same in
// so many words: a reffed copy of the original buffer.
return Gst.GstNative.MiniObjectRef(buffer);
}

vfuncDefaults.GstBase.Aggregator::clip:
{
// Nothing below the override clips, so the buffer is handed back as it
// arrived, carrying the reference the caller gave up.
return buf;
}

vfuncDefaults.GstBase.BaseParse::get_sink_caps:
{
// gstbaseparse.c:1660-1688 - there is no function below the override to
// reach: gst_base_parse_sink_query does the work inline when the slot is
// NULL, answering the caps of the sink pad template intersected with the
// filter, or those caps as they are when there is no filter.
return Gst.Base.BaseParseDefaults.GetSinkCaps(parse, filter);
}

vfuncDefaults.GstBase.BaseParse::pre_push_frame:
{
// gstbaseparse.c:2606-2610 - the implementation below the override marks
// the frame for clipping and answers Ok; it touches nothing else, which is
// what makes it the no-op the base class installs.
Gst.Base.BaseParseDefaults.MarkFrameForClipping(frame);
return Gst.FlowReturn.Ok;
}

vfuncDefaults.GstBase.PushSrc::alloc:
{
// gst_push_src_alloc falls back to gst_base_src_default_alloc, the pooled
// allocation, when the GstPushSrcClass slot is NULL. No class of the library
// sets that slot, so the chain-up has to reach that implementation itself.
return Gst.Base.BaseSrcDefaults.Alloc(src, buf);
}
